/* @autogenerated */
import { ObservedSourceRepository } from 'app/features/observe/observed-source/repository/observed-source-repository.service';
import { normalizeHeader } from 'app/shared/toolkit/entity-import/column-match';
import {
  OBSERVED_EMBED_EXCEL_COLUMNS,
  OBSERVED_EMBED_EXCEL_SENSITIVE,
} from 'app/features/observe/observed-embed/model/observed-embed-excel-columns';
import { take, map } from 'rxjs';
import { ObservedEmbedRepository } from 'app/features/observe/observed-embed/repository/observed-embed-repository.service';
import { BaseImportAction } from 'app/shared/toolkit/action/base-import-action';
import { ImportDefinition } from 'app/shared/toolkit/entity-import/entity-import.model';
import { ObservedEmbed } from 'app/features/observe/observed-embed/model/observed-embed.model';
import { Component, inject } from '@angular/core';
import { ObservedDashboardRepository } from 'app/features/observe/observed-dashboard/repository/observed-dashboard-repository.service';

/** Candidatos que pide cada búsqueda: el filtro puede no ser exacto y se comprueba aquí. */
const LOOKUP_LIMIT = 50;

@Component({
  selector: 'observed-embed-view-import-action',
  standalone: false,
  templateUrl: './observed-embed-view-import-action.component.html',
})
export class ObservedEmbedViewImportActionComponent extends BaseImportAction<ObservedEmbed> {
  protected readonly scope = 'observe/observed-embed';
  protected readonly repository = inject(ObservedEmbedRepository);
  private readonly dashboardRepository = inject(ObservedDashboardRepository);
  private readonly originRepository = inject(ObservedSourceRepository);

  readonly definition: ImportDefinition<ObservedEmbed> = {
    storageKey: 'observe.observed-embed',
    scope: this.scope,
    // Clave natural (índice único del modelo): una fila con los mismos valores actualiza el elemento
    keys: ['tokenHash'],
    columns: OBSERVED_EMBED_EXCEL_COLUMNS,
    sensitive: OBSERVED_EMBED_EXCEL_SENSITIVE,
    // Campos que el backend solo cambia con sus acciones: se aplican tras crear o actualizar
    actions: {
      enabled: [
        { name: 'enable', value: true, run: (item) => this.repository.enable(item.uid) },
        { name: 'disable', value: false, run: (item) => this.repository.disable(item.uid) },
      ],
    },
    references: {
      dashboard: {
        resolve: (text) =>
          this.dashboardRepository.values({ search: text, limit: LOOKUP_LIMIT }).pipe(
            take(1),
            map((found) => {
              const wanted = normalizeHeader(text);
              const one = found.find(
                (candidate) => candidate.uid === text || normalizeHeader(candidate.name) === wanted,
              );
              return one ? { $ref: one.uid } : null;
            }),
          ),
      },
      origin: {
        resolve: (text) =>
          this.originRepository.values({ search: text, limit: LOOKUP_LIMIT }).pipe(
            take(1),
            map((found) => {
              const wanted = normalizeHeader(text);
              const one = found.find(
                (candidate) => candidate.uid === text || normalizeHeader(candidate.code) === wanted,
              );
              return one ? { $ref: one.uid } : null;
            }),
          ),
      },
    },
    defaults: () => ({ maxRange: 'day', minRefresh: 60, allowRaw: false, enabled: false }),
    display: (values) => String(values.name ?? ''),
    target: {
      acl: () => this.repository.checkAcl(),
      find: (values) =>
        this.repository.values({ tokenHash: values.tokenHash, limit: LOOKUP_LIMIT }).pipe(
          take(1),
          map((found) => found.filter((item) => item.tokenHash === values.tokenHash)),
        ),
      add: (item) => this.repository.add(item),
      update: (item) => this.repository.update(item),
      context: this.repository.context(),
    },
  };
}
